"""Unit H: Python for cybersecurity and automation. Defensive and offline: sample data only, no network, no subprocess in anything executable."""

from __future__ import annotations

from app.services.python_practice.content.build import mcq as M, out as O


def questions() -> list[dict]:
    return [
        O("log-parsing", "easy", "What is printed for this sample log line?", "line = '2024-05-01 10:00:03 WARN auth failed user=alice ip=203.0.113.9'\ndate, time, level, *rest = line.split()\nprint(level, ' '.join(rest))", "WARN auth failed user=alice ip=203.0.113.9", ["2024-05-01 WARN", "WARN auth", "['WARN', 'auth', 'failed']"], "Star-unpacking splits the date, time and level, leaving the remaining message words in a list."),
        O("log-parsing", "medium", "What is printed?", "lines = ['a ERROR x', 'b INFO y', 'c ERROR z']\nerrors = [l.split()[0] for l in lines if ' ERROR ' in l]\nprint(errors, len(errors) / len(lines) > 0.5)", "['a', 'c'] True", ["['a', 'c'] False", "['ERROR', 'ERROR'] True", "['b'] False"], "Two of three lines are errors (0.667 > 0.5)."),
        O("ip-validation", "easy", "What is printed?", "import ipaddress\nfor s in ['192.168.1.10', '256.1.1.1', '::1']:\n    try:\n        print(ipaddress.ip_address(s).version, end=' ')\n    except ValueError:\n        print('bad', end=' ')", "4 bad 6", ["4 4 6", "4 bad bad", "bad bad 6"], "ip_address parses IPv4 and IPv6 and raises ValueError for invalid text; 256 is out of range."),
        O("ip-validation", "medium", "What is printed?", "import ipaddress\nnet = ipaddress.ip_network('10.0.0.0/24')\nip = ipaddress.ip_address('10.0.0.77')\nprint(ip in net, ip.is_private, net.num_addresses, ipaddress.ip_address('8.8.8.8').is_private)", "True True 256 False", ["True True 254 False", "False True 256 False", "True False 256 True"], "/24 holds 256 addresses (254 usable hosts). 10.0.0.0/8 is private; 8.8.8.8 is public."),
        O("url-parsing", "medium", "What is printed?", "from urllib.parse import urlparse, parse_qs\nu = urlparse('https://example.com:8443/a/b?x=1&y=2&x=3#top')\nprint(u.scheme, u.hostname, u.port, u.path, parse_qs(u.query)['x'])", "https example.com 8443 /a/b ['1', '3']", ["https example.com:8443 8443 /a/b ['3']", "https example.com 8443 /a/b ['1']", "https example.com 8443 /a ['1', '3']"], "urlparse splits the URL without network access; parse_qs returns lists because keys can repeat."),
        M("url-parsing", "medium", "Why is checking `url.startswith('https://example.com')` a weak allow-list test?", "'https://example.com.evil.test' and 'https://example.com@evil.test' also start with it; parse the URL and compare the hostname exactly", ["startswith is slow", "It only works for http", "It is case insensitive"], "Validate parsed components (scheme and hostname) against an allow-list, not substrings."),
        O("file-hashing", "medium", "What is printed?", "import hashlib\nprint(hashlib.sha256(b'abc').hexdigest()[:16], hashlib.md5(b'').hexdigest())", "ba7816bf8f01cfea d41d8cd98f00b204e9800998ecf8427e", ["a9993e364706816a d41d8cd98f00b204e9800998ecf8427e", "ba7816bf8f01cfea 900150983cd24fb0d6963f7d28e17f72", "ba7816bf8f01cfea e3b0c44298fc1c14"], "SHA-256('abc') starts with ba7816bf8f01cfea; MD5 of empty input is d41d8cd98f00b204e9800998ecf8427e."),
        M("file-hashing", "medium", "For verifying file integrity against a published checksum, which choice is best?", "SHA-256 (or better), reading the file in chunks, and comparing with hmac.compare_digest", ["MD5, since it is fastest", "Compare file sizes only", "Compare the first 100 bytes"], "MD5 and SHA-1 are collision-prone; chunked reads keep memory constant; constant-time comparison avoids timing leaks for secret values."),
        O("json-logs", "medium", "What is printed?", "import json\nrecs = [json.loads(l) for l in ['{\"u\": \"a\", \"ok\": false}', '{\"u\": \"b\", \"ok\": true}', '{\"u\": \"a\", \"ok\": false}']]\nfails = {}\nfor r in recs:\n    if not r['ok']:\n        fails[r['u']] = fails.get(r['u'], 0) + 1\nprint(fails)", "{'a': 2}", ["{'a': 1, 'b': 0}", "{'a': 2, 'b': 1}", "['a', 'a']"], "Each JSON line is parsed separately; only failed records are counted per user."),
        M("json-logs", "medium", "A JSON-lines log file has one corrupt line. What should the processor do?", "Catch json.JSONDecodeError per line, count or log the bad line, and continue", ["Crash the whole run", "Silently drop the entire file", "Retry the same line forever"], "Robust log pipelines tolerate malformed records and report how many were skipped."),
        O("csv-reports", "medium", "What is printed?", "import csv, io\nbuf = io.StringIO()\nw = csv.writer(buf)\nw.writerow(['user', 'note'])\nw.writerow(['amy', 'said \"hi\", left'])\nprint(buf.getvalue().splitlines())", "['user,note', 'amy,\"said \"\"hi\"\", left\"']", ["['user,note', 'amy,said \"hi\", left']", "['user,note', 'amy,\"said \"hi\", left\"']", "['user note', 'amy said hi left']"], "The csv writer quotes fields containing commas and doubles embedded quotes."),
        M("csv-reports", "medium", "A CSV report is opened in a spreadsheet. A user-supplied cell starts with '=' and could run as a formula. What is the defence?", "Prefix such cells with a single quote (or otherwise neutralise a leading = + - @) before writing", ["Nothing, spreadsheets are safe", "Convert the file to UTF-16", "Only allow numeric columns"], "CSV/formula injection is prevented by neutralising leading formula characters in untrusted fields."),
        O("regex-extraction", "medium", "What is printed?", "import re\nlog = 'Failed password for root from 198.51.100.4 port 22; Accepted for bob from 203.0.113.7 port 22'\nprint(re.findall(r'from (\\d{1,3}(?:\\.\\d{1,3}){3})', log))", "['198.51.100.4', '203.0.113.7']", ["['root', 'bob']", "['198.51.100.4']", "['22', '22']"], "The capture group returns just the IPs after 'from '; the non-capturing group (?:...) repeats the dotted octets."),
        M("regex-extraction", "hard", "Why validate regex-extracted IPs with ipaddress afterwards?", "A pattern like \\d{1,3}(\\.\\d{1,3}){3} also matches 999.999.999.999, which is not a valid address", ["Regex cannot match digits", "ipaddress is faster", "Regex always rejects IPv6"], "Regex finds candidates; the standard library validates them. Also beware catastrophic backtracking on untrusted input."),
        O("event-analysis", "medium", "What is printed?", "events = [('10:00', 'bob', 'fail'), ('10:01', 'bob', 'fail'), ('10:02', 'bob', 'fail'), ('10:03', 'amy', 'fail'), ('10:04', 'bob', 'ok')]\nfrom collections import Counter\nc = Counter(u for _, u, r in events if r == 'fail')\nprint([u for u, n in c.items() if n >= 3])", "['bob']", ["['bob', 'amy']", "['amy']", "[]"], "Counting failures per user and flagging a threshold is the core of simple brute-force detection; real detection also uses time windows."),
        M("event-analysis", "medium", "Which improvement most reduces false positives in a 'repeated failed logins' alert?", "Count failures within a sliding time window per account and source, not over the whole file", ["Alert on any single failure", "Ignore the usernames", "Count only successful logins"], "A time window separates a brute-force burst from a user who mistyped over a week."),
        O("file-automation", "medium", "What is printed?", "from pathlib import Path\nd = Path('/tmp/auto_demo'); d.mkdir(exist_ok=True)\nfor n in ['a.log', 'b.txt', 'c.log']:\n    (d / n).write_text(n)\nlogs = sorted(p.name for p in d.iterdir() if p.suffix == '.log')\nprint(logs)", "['a.log', 'c.log']", ["['a.log', 'b.txt', 'c.log']", "['b.txt']", "[]"], "Filtering iterdir() by suffix selects the log files; sorting makes the order deterministic."),
        M("file-automation", "medium", "Before an automation script deletes files matching a pattern, what is the safest practice?", "Support a dry-run that only lists matches, and restrict the operation to an expected directory", ["Run it as root to avoid permission errors", "Use a very broad glob like **/*", "Delete first and check later"], "Dry runs and strict path boundaries prevent catastrophic deletions."),
        O("http-analysis", "medium", "What is printed for these recorded (offline) responses?", "responses = [{'status': 200, 'headers': {'content-type': 'text/html'}}, {'status': 403, 'headers': {}}, {'status': 200, 'headers': {'server': 'x', 'x-frame-options': 'DENY'}}]\nok = [r for r in responses if r['status'] == 200]\nmissing = [i for i, r in enumerate(ok) if 'x-frame-options' not in r['headers']]\nprint(len(ok), missing)", "2 [0]", ["3 [0, 1]", "2 [1]", "1 [0]"], "Analysis of recorded responses needs no network: filter 200s, then flag the ones lacking a security header."),
        M("http-analysis", "medium", "Which of these is a security-relevant HTTP response header?", "Content-Security-Policy", ["Content-Length only", "Accept-Language", "Date"], "CSP, Strict-Transport-Security, X-Content-Type-Options and X-Frame-Options help harden browser behaviour."),
        M("secure-subprocess", "medium", "Which approach is safest for running an external program with a user-provided filename?", "Pass the program and its arguments as a list to subprocess.run, with the shell left disabled", ["Build one command string by concatenating the filename and let the shell run it", "Call the operating system's shell helper with an f-string containing the filename", "Evaluate the command text as Python"], "An argument list is not parsed by a shell, which prevents command injection such as `file; rm -rf ~`. Also validate the filename and set a timeout.", code="import subprocess\nsubprocess.run(['grep', '-n', 'ERROR', filename], check=True, timeout=10)"),
        M("secure-subprocess", "hard", "What does shell=False NOT protect you from?", "Option injection: a user value that starts with '-' can still be read as a flag, so pass '--' or validate it", ["Any use of external programs", "Spaces in filenames", "Unicode filenames"], "Arguments are not parsed by a shell, but the program itself may interpret leading dashes as options."),
        O("input-validation", "medium", "What is printed?", "import re\ndef valid_user(s):\n    return bool(re.fullmatch(r'[a-z][a-z0-9_]{2,15}', s))\n\nprint(valid_user('ann_1'), valid_user('1ann'), valid_user('a'), valid_user('x' * 17), valid_user('ann\\n'))", "True False False False False", ["True False False False True", "True True False False False", "True False False True False"], "fullmatch requires the entire string to fit; unlike `$` with match, it rejects a trailing newline."),
        M("input-validation", "medium", "Which approach to validating input is generally strongest?", "Allow-list: accept only known-good patterns, lengths and types, and reject everything else", ["Block-list the known bad characters", "Trust client-side validation", "Escape later and hope"], "Deny lists miss variants; allow lists define exactly what is valid. Always validate on the server."),
        O("automation-exceptions", "medium", "What is printed?", "results = []\nfor name in ['a', 'bad', 'c']:\n    try:\n        if name == 'bad':\n            raise ValueError('corrupt')\n        results.append(name.upper())\n    except ValueError as e:\n        results.append(f'skip:{e}')\nprint(results)", "['A', 'skip:corrupt', 'C']", ["['A']", "['A', 'C']", "ValueError"], "Catching per item lets a batch continue and records what failed instead of aborting."),
        M("automation-exceptions", "medium", "A nightly automation script fails silently. What is the best fix?", "Log the exception with context, return a non-zero exit code and alert", ["Wrap everything in try/except: pass", "Print 'done' regardless", "Delete the log file"], "Operators need failures to be visible; silent success is worse than a loud failure."),
        M("secret-management", "easy", "Where is the safest place to keep an API token for a Python script?", "An environment variable or a secrets manager, never in the repository", ["A constant in the source file", "A comment in the code", "A public gist"], "Committed secrets stay in git history even after deletion; rotate any secret that was committed."),
        M("secret-management", "medium", "Which logging line is a security problem?", "logger.info('login ok password=%s', password)", ["logger.info('login ok user=%s', user_id)", "logger.info('request took %d ms', ms)", "logger.warning('3 failed attempts for user_id=%s', user_id)"], "Never log passwords, tokens or full credentials; log identifiers and outcomes only."),
        O("untrusted-input", "medium", "What is printed?", "import json\nraw = '{\"n\": \"5; DROP TABLE x\"}'\nn = json.loads(raw)['n']\ntry:\n    print(int(n))\nexcept ValueError:\n    print('rejected')", "rejected", ["5", "5; DROP TABLE x", "TypeError"], "Converting to the expected type rejects malicious text; for databases also use parameterised queries."),
        M("untrusted-input", "hard", "Why is pickle.loads(data) dangerous on untrusted data?", "Unpickling can execute arbitrary code during deserialisation; use a data format like JSON instead", ["Pickle is slower than JSON", "Pickle cannot store dictionaries", "It only works on Windows"], "Never unpickle data from an untrusted source. Prefer JSON or another non-executable format."),
    ]
